CREATE FUNCTION population_top3000_202608_202609_v1.ctx06_aug03_reason_v5(identity_ok boolean,anchor_count int,prior_count int,current_count int,prior_close numeric,current_close numeric,p_prior_date date,p_current_date date)RETURNS text LANGUAGE sql IMMUTABLE SET search_path='pg_catalog' AS $$SELECT CASE WHEN identity_ok IS DISTINCT FROM true THEN 'UNRESOLVED_IDENTITY_OR_DATE' WHEN anchor_count IS DISTINCT FROM 1 THEN 'AMBIGUOUS_OR_MISSING_ANCHOR' WHEN prior_count IS DISTINCT FROM 1 OR current_count IS DISTINCT FROM 1 THEN 'MISSING_OR_DUPLICATE_MATCHED_PRICE' WHEN p_prior_date IS DISTINCT FROM date'2026-07-31' OR p_current_date IS DISTINCT FROM date'2026-08-03' THEN 'SOURCE_DATE_MISMATCH' WHEN prior_close IS NULL OR current_close IS NULL OR prior_close NOT BETWEEN 1e-100 AND 1e100 OR current_close NOT BETWEEN 1e-100 AND 1e100 OR prior_close::text IN('NaN','Infinity','-Infinity') OR current_close::text IN('NaN','Infinity','-Infinity') THEN 'INVALID_OR_NULL_CLOSE' END$$;
